-- Gradiente · más cosas que edita el equipo (organizadores y admins) desde la página.
-- Los datos de data/*.json quedan de respaldo si Supabase no responde.

-- 1) avisos marcados en el calendario (paros, días sin clases, eventos)
alter table public.avisos add column in_cal boolean not null default true;
grant select (in_cal) on public.avisos to anon, authenticated;

-- 2) links útiles (Recursos)
create table public.links (
  id          uuid primary key default gen_random_uuid(),
  title       text not null check (char_length(title) between 2 and 120),
  label       text check (char_length(label) <= 120),
  url         text not null check (url ~* '^(https?://|mailto:|/|#)' and char_length(url) <= 500),
  category    text not null default 'Otros' check (char_length(category) <= 40),
  description text check (char_length(description) <= 300),
  tags        text[] not null default '{}',
  audience    text[] not null default '{}',
  priority    integer not null default 50,
  active      boolean not null default true,
  updated_at  timestamptz not null default now()
);
alter table public.links enable row level security;
create policy "links: ver"            on public.links for select to anon, authenticated using (active or (select public.is_staff()));
create policy "links: el equipo crea" on public.links for insert to authenticated with check ((select public.is_staff()));
create policy "links: el equipo edita" on public.links for update to authenticated using ((select public.is_staff())) with check ((select public.is_staff()));
create policy "links: el equipo borra" on public.links for delete to authenticated using ((select public.is_staff()));
create trigger links_touch before update on public.links for each row execute function public.kiosco_touch();

-- 3) preguntas frecuentes (chat de Ayuda)
create table public.faq (
  id          text primary key check (id ~ '^[a-z0-9-]{2,40}$'),
  topic       text not null check (char_length(topic) <= 40),
  q           text not null check (char_length(q) between 4 and 200),
  a           text[] not null check (cardinality(a) between 1 and 8),
  k           text[] not null default '{}',
  links       jsonb not null default '[]'::jsonb,
  top         integer,
  priority    integer not null default 50,
  active      boolean not null default true,
  updated_at  timestamptz not null default now()
);
alter table public.faq enable row level security;
create policy "faq: ver"            on public.faq for select to anon, authenticated using (active or (select public.is_staff()));
create policy "faq: el equipo crea" on public.faq for insert to authenticated with check ((select public.is_staff()));
create policy "faq: el equipo edita" on public.faq for update to authenticated using ((select public.is_staff())) with check ((select public.is_staff()));
create policy "faq: el equipo borra" on public.faq for delete to authenticated using ((select public.is_staff()));
create trigger faq_touch before update on public.faq for each row execute function public.kiosco_touch();

-- 4) cátedras: correcciones de página y mail por código de materia (lo demás sale de data/catedras.json)
create table public.catedras (
  code        text primary key check (code ~ '^[A-Za-z0-9]{2,12}$'),
  page        text check (char_length(page) <= 200),
  mail        text check (mail is null or mail ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  updated_at  timestamptz not null default now()
);
alter table public.catedras enable row level security;
create policy "catedras: ver"            on public.catedras for select to anon, authenticated using (true);
create policy "catedras: el equipo crea" on public.catedras for insert to authenticated with check ((select public.is_staff()));
create policy "catedras: el equipo edita" on public.catedras for update to authenticated using ((select public.is_staff())) with check ((select public.is_staff()));
create policy "catedras: el equipo borra" on public.catedras for delete to authenticated using ((select public.is_staff()));
create trigger catedras_touch before update on public.catedras for each row execute function public.kiosco_touch();

grant select on public.links, public.faq, public.catedras to anon, authenticated;



-- cátedras: la tabla guarda solo las correcciones del equipo; la app las aplica encima de data/catedras.json
