  ('Becas Fundacion YPF', 'Becas Fundación YPF', 'https://becas.fundacionypf.org/', 'Becas y bienestar', 'Becas para carreras de ingeniería y energía.', array['ypf','beca','ingenieria']::text[], array['todos']::text[], 9, true),
  ('Proyectos de extension FI', 'Proyectos de extensión', 'https://ing.unlp.edu.ar/extension/proyectos-de-extension/', 'Proyectos e investigacion', 'Proyectos con la comunidad a los que podés sumarte.', array['extension','proyectos','participar']::text[], array['todos']::text[], 1, true),
  ('Convocatorias de extension FI', 'Convocatorias de extensión', 'https://ing.unlp.edu.ar/extension/', 'Proyectos e investigacion', 'Llamados abiertos y actividades (sirven como AFC).', array['convocatorias','extension','afc']::text[], array['todos']::text[], 2, true),
  ('Proyectos de investigacion y transferencia', 'Investigación y transferencia', 'https://ing.unlp.edu.ar/investigacion/proyectos-de-investigacion-y-transferencia/', 'Proyectos e investigacion', 'Los proyectos que se desarrollan en la FI.', array['investigacion','transferencia','proyectos']::text[], array['estudiantes','avanzados','todos']::text[], 3, true),
