  ('Estudiantes FI (tramites, certificados y servicios)', 'Estudiantes FI', 'https://ing.unlp.edu.ar/estudiantes/', 'Institucional', 'Certificados, trámites y servicios para alumnos.', array['estudiantes','tramites','oficial']::text[], array['todos']::text[], 1, true),
  ('Servicios IT FI', 'Servicios IT', 'https://ing.unlp.edu.ar/institucional/servicios_it/', 'Institucional', 'Wifi, cuentas y sistemas de la Facultad.', array['it','moodle','correo']::text[], array['todos']::text[], 3, true),
