  ('Direccion de Ensenanza: ensenanza@ing.unlp.edu.ar', 'Dirección de Enseñanza', 'mailto:ensenanza@ing.unlp.edu.ar', 'Contacto', 'Inscripciones, finales y equivalencias.', array['mail','copiar','ensenanza']::text[], array['todos']::text[], 98, true),
