insert into public.faq (id, topic, q, a, k, links, top, priority) values
  ('inscripcion', 'cursada', '¿Cómo me inscribo a una materia?', array['Por SIU Guaraní, dentro del período de inscripción que publica la Facultad en el calendario académico.','Si la materia no te aparece, casi siempre es porque te falta alguna correlativa. En Mi plan podés ver qué te falta.']::text[], array['inscribir','inscripcion','anotar','anoto','anotarme','cursar','materia','cursada','siu']::text[], '[{"label":"SIU Guaraní","url":"https://autogestion.guarani.unlp.edu.ar/acceso"},{"label":"Calendario académico","match":"Calendario ano lectivo completo"}]'::jsonb, 1, 1),
  ('que-curso', 'cursada', '¿Qué materias puedo cursar?', array['Depende de las correlativas: para cursar necesitás tenerlas regulares o aprobadas.','Marcá lo que ya hiciste en Mi plan y te mostramos al toque qué podés cursar y qué finales podés rendir.']::text[], array['puedo','cursar','correlativas','correlativa','habilita','siguiente','cuatrimestre','plan']::text[], '[{"label":"Ver qué puedo cursar","go":"#/plan?filtro=ready"}]'::jsonb, 3, 2),
  ('aulas', 'cursada', '¿Dónde veo aulas y horarios?', array['La Facultad publica las aulas y horarios de cada cuatrimestre en su web. Las cátedras suelen avisar cambios en el portal de asignaturas.']::text[], array['aula','aulas','horario','horarios','donde','curso','comision','comisiones','edificio']::text[], '[{"label":"Aulas y horarios","match":"Aulas y horarios"},{"label":"Portal de asignaturas","match":"Portal de Asignaturas FI"}]'::jsonb, 2, 3),
  ('regular', 'cursada', '¿Qué diferencia hay entre regular y aprobada?', array['Regular: aprobaste la cursada y te queda rendir el final.','Aprobada: rendiste el final o la promocionaste. Para rendir un final necesitás las correlativas aprobadas, no solo regulares.']::text[], array['regular','regularizar','aprobada','aprobar','diferencia','promocion','promocionar','final']::text[], '[]'::jsonb, null, 4),
  ('material', 'cursada', '¿Dónde encuentro el material de una materia?', array['Cada cátedra tiene su página en el portal de asignaturas de la Facultad.','Además, en la Nube de Gradiente hay más de 2.600 archivos entre parciales, finales y apuntes, ordenados por materia.']::text[], array['material','apunte','apuntes','teoria','practica','catedra','pagina','moodle','asignatura']::text[], '[{"label":"Portal de asignaturas","match":"Portal de Asignaturas FI"},{"label":"Nube de apuntes","match":"Nube de apuntes y parciales"}]'::jsonb, null, 5),
  ('final-inscripcion', 'finales', '¿Cómo me anoto a un final?', array['También por SIU Guaraní, en las fechas de mesa que figuran en el calendario académico. Anotate con tiempo: la inscripción cierra unos días antes de cada mesa.','Acordate que para rendir necesitás las correlativas aprobadas.']::text[], array['final','finales','mesa','mesas','rendir','examen','anotar','inscribir','fecha','fechas']::text[], '[{"label":"SIU Guaraní","url":"https://autogestion.guarani.unlp.edu.ar/acceso"},{"label":"Calendario académico","match":"Calendario ano lectivo completo"}]'::jsonb, 4, 6),
  ('prorroga', 'finales', 'Se me vence la cursada, ¿puedo pedir prórroga?', array['Sí, la Facultad tiene un formulario para pedir prórroga para rendir el final. Pedila antes de que se venza.']::text[], array['vence','vencimiento','vencio','prorroga','extender','extension','cursada','regularidad','final']::text[], '[{"label":"Pedir prórroga","match":"Prorroga para rendir final"}]'::jsonb, null, 7),
  ('parciales-viejos', 'finales', '¿Dónde consigo parciales y finales viejos?', array['En la Nube de Gradiente: más de 2.600 archivos ordenados por materia. En Mi plan te marcamos con una carpetita las materias que tienen material.']::text[], array['parcial','parciales','final','finales','viejos','resueltos','modelo','nube','drive','examenes']::text[], '[{"label":"Abrir la nube","match":"Nube de apuntes y parciales"}]'::jsonb, 5, 8),
  ('siu-cuenta', 'tramites', '¿Cómo creo mi cuenta de SIU Guaraní?', array['Desde la página de acceso de SIU Guaraní de la UNLP. Si ya tenés cuenta y no podés entrar, probá recuperar la contraseña desde ahí mismo.']::text[], array['siu','guarani','cuenta','usuario','contrasena','clave','entrar','acceso','olvide']::text[], '[{"label":"Ir a SIU Guaraní","url":"https://autogestion.guarani.unlp.edu.ar/acceso"}]'::jsonb, null, 9),
  ('certificado', 'tramites', '¿Cómo saco un certificado o constancia?', array['Los trámites, certificados y servicios para estudiantes están explicados en la página de Estudiantes de la Facultad. Si hace falta ir en persona, sacá turno antes.']::text[], array['certificado','constancia','alumno','regular','analitico','tramite','tramites','papel']::text[], '[{"label":"Trámites de estudiantes","match":"Estudiantes FI (tramites, certificados y servicios)"},{"label":"Sacar turno","match":"Turnos FI para tramites"}]'::jsonb, null, 10),
  ('turno', 'tramites', '¿Cómo saco turno para un trámite?', array['La Facultad da turnos online para la atención presencial.']::text[], array['turno','turnos','alumnos','departamento','atencion','presencial','ventanilla']::text[], '[{"label":"Sacar turno","match":"Turnos FI para tramites"}]'::jsonb, null, 11),
  ('correo', 'tramites', '¿Cómo pido el correo institucional?', array['Se pide desde la web de soporte de la Facultad.']::text[], array['correo','mail','email','institucional','cuenta','ing']::text[], '[{"label":"Pedir correo","match":"Solicitud de correo institucional para alumnos"}]'::jsonb, null, 12),
  ('mail-profe', 'profes', '¿Cómo consigo el mail de un profe o de la cátedra?', array['Buscá la materia y te mostramos el mail de contacto de la cátedra, su página y el Portal de Asignaturas. Casi todas tienen un mail general que lee el equipo docente.','Para dudas del día a día, el aula virtual de la materia suele ser lo más rápido.']::text[], array['mail','correo','email','profe','profesor','profesora','docente','catedra','contacto','escribir','ayudante','jtp','titular']::text[], '[{"label":"Buscar el mail de la cátedra","go":"catedra"},{"label":"Portal de asignaturas","match":"Portal de Asignaturas FI"}]'::jsonb, null, 13),
  ('escribir-profe', 'profes', '¿Cómo le escribo a un profe para hacer una consulta?', array['Mandalo desde tu mail institucional si lo tenés. En el asunto poné materia, comisión y tema (por ejemplo: «Matemática B – Com. 3 – Consulta TP 2»).','Arrancá con nombre, apellido y número de alumno, y andá al grano. Si es una duda de contenido, muchas veces conviene ir directo a la clase de consulta.']::text[], array['escribir','mail','consulta','profe','profesor','docente','asunto','redactar','mensaje','como','pregunto']::text[], '[{"label":"Buscar el mail de la cátedra","go":"catedra"},{"label":"Pedir correo institucional","match":"Solicitud de correo institucional para alumnos"}]'::jsonb, null, 14),
  ('horario-consulta', 'profes', '¿Cuándo son las clases de consulta?', array['Cada cátedra tiene sus propios horarios de consulta. Suelen estar en la página de la cátedra o en su aula virtual.','Si no los encontrás, escribile al mail de contacto de la cátedra y preguntá.']::text[], array['consulta','consultas','horario','horarios','clase','dudas','practica','ayudante']::text[], '[{"label":"Buscar la cátedra","go":"catedra"},{"label":"Aulas y horarios","match":"Aulas y horarios"}]'::jsonb, null, 15),
  ('revision', 'profes', 'No estoy de acuerdo con mi nota, ¿qué hago?', array['Pedí ver el examen: la revisión es tu derecho. La cátedra suele avisar en el aula virtual cuándo es la muestra de parciales; si no, preguntá por mail.','Si después de la revisión sentís que algo no estuvo bien, escribinos y te acompañamos.']::text[], array['nota','revision','revisar','examen','parcial','reclamo','corregir','correccion','muestra','desaprobe','injusto']::text[], '[{"label":"Buscar el mail de la cátedra","go":"catedra"},{"label":"Escribirnos","go":"consulta"}]'::jsonb, null, 16),
  ('problema-catedra', 'profes', 'Tengo un problema con un profe o una cátedra', array['Primero intentá hablarlo con la cátedra (tu ayudante, el JTP o el titular). Si no se resuelve, podés ir al Departamento de tu carrera o a la Dirección de Enseñanza.','Si no querés hacerlo solo, escribinos: como agrupación te acompañamos y lo tratamos con discreción.']::text[], array['problema','profe','profesor','catedra','trato','maltrato','reclamo','queja','denuncia','conflicto','injusto']::text[], '[{"label":"Escribirnos","go":"consulta"},{"label":"Mail a Enseñanza","url":"mailto:ensenanza@ing.unlp.edu.ar"}]'::jsonb, null, 17),
  ('paro', 'cursada', '¿Hay clases? ¿Hay paro o feriado?', array['En el calendario del inicio están los feriados, asuetos y fechas de la Facultad. Cuando hay paro o un aviso importante, también lo marcamos ahí.']::text[], array['paro','clases','feriado','asueto','hay','manana','hoy','calendario','fecha','fechas','suspension','no laborable']::text[], '[{"label":"Ver el calendario","go":"cal"},{"label":"Calendario oficial","match":"Calendario ano lectivo completo"}]'::jsonb, null, 18),
  ('contacto-facu', 'tramites', '¿A quién le escribo por un problema con la cursada?', array['Para temas académicos (inscripciones, correlativas, mesas) escribile a la Dirección de Enseñanza. Para becas y bienestar, a Asuntos Estudiantiles.','Si no sabés por dónde arrancar, mandanos la consulta y te orientamos.']::text[], array['problema','reclamo','escribir','mail','contacto','ensenanza','asuntos','estudiantiles','ayuda']::text[], '[{"label":"Mail a Enseñanza","url":"mailto:ensenanza@ing.unlp.edu.ar"},{"label":"Mail a Asuntos Estudiantiles","url":"mailto:asuntos.estudiantiles@ing.unlp.edu.ar"}]'::jsonb, null, 19),
  ('becas', 'becas', '¿Qué becas hay?', array['Hay becas de la Facultad y de la UNLP (ayuda económica, comedor, transporte, entre otras). Las convocatorias abren en fechas puntuales, así que conviene revisar seguido.']::text[], array['beca','becas','plata','ayuda','economica','comedor','transporte','bienestar']::text[], '[{"label":"Becas y pasantías","match":"Becas y pasantias FI"}]'::jsonb, null, 20),
  ('trabajo', 'becas', 'Trabajo, ¿hay algo para estudiantes que trabajan?', array['Sí, la Facultad tiene un programa para estudiantes trabajadores (RET) con algunas facilidades para la cursada.']::text[], array['trabajo','trabajador','trabajadora','laburo','laburo','ret','horario','facilidades']::text[], '[{"label":"Programa RET","match":"Programa para estudiantes trabajadores (RET)"}]'::jsonb, null, 21),
  ('ingresante', 'ingreso', 'Soy ingresante, ¿por dónde arranco?', array['Empezá por la guía oficial para ingresantes y la página de la cátedra de ingreso. Creá tu cuenta de SIU Guaraní, que la vas a usar para todo.','Y cuando termines el ingreso, armá tu plan acá para ver qué cursar.']::text[], array['ingresante','ingreso','nuevo','nueva','empiezo','primer','primero','arranco','curso','nivelacion']::text[], '[{"label":"Guía para ingresantes","match":"Guia oficial para ingresantes FI-UNLP"},{"label":"Cátedra de ingreso","match":"Catedra de ingreso"}]'::jsonb, null, 22),
  ('que-es', 'gradiente', '¿Qué es Gradiente?', array['Somos una agrupación estudiantil de Ingeniería UNLP. Hacemos la Nube de apuntes, la mesita de librería en Electro, esta web y te ayudamos con lo que necesites.']::text[], array['gradiente','agrupacion','quienes','somos','centro','estudiantes']::text[], '[{"label":"Conocenos","go":"about"}]'::jsonb, null, 23),
  ('mesita', 'gradiente', '¿Dónde está la mesita y qué vende?', array['Estamos con la mesita en el edificio de Electro. Tenemos kits de cuadernos y útiles a precio estudiante.']::text[], array['mesita','kiosco','libreria','cuaderno','utiles','comprar','precio','electro','kit']::text[], '[{"label":"Ver la mesita","go":"#/mesita"}]'::jsonb, null, 24),
  ('sumarme', 'gradiente', '¿Cómo me sumo a Gradiente?', array['¡Escribinos! Por Instagram, WhatsApp o pasando por la mesita en Electro.']::text[], array['sumo','sumarme','participar','militar','unirme','ayudar','voluntario']::text[], '[{"label":"Instagram","url":"https://instagram.com/gradienteingenieriaunlp"},{"label":"WhatsApp","url":"https://chat.whatsapp.com/CRnDHAhup938Nk4uJ8TBVp"}]'::jsonb, null, 25);
